CREATE OR ALTER VIEW v_dispatch_detail AS SELECT h.*, l.[工序编码], l.[工序名称], l.[工作中心], l.[设备], l.[班组], l.[工人], l.[加工类型], l.[计划数量], l.[已派工数量], l.[派工数量], l.[计量单位], l.[派工加工状态], l.[累计汇报数量], l.[委外供应商], l.[规格型号] FROM bd_dispatch h LEFT JOIN bl_dispatch l ON h.[单据编号]=l.[单据编号]
GO
CREATE OR ALTER VIEW v_dispatch_stats AS SELECT ROW_NUMBER() OVER(ORDER BY (SELECT NULL)) AS id, h.[单据日期], h.asp_cancel, l.[生产车间], l.[工序名称], l.[计量单位], COUNT(DISTINCT h.[单据编号]) AS [派工单数], SUM(COALESCE(l.[计划数量],0)) AS [计划数量], SUM(COALESCE(l.[派工数量],0)) AS [派工数量], SUM(COALESCE(l.[累计汇报数量],0)) AS [累计汇报数量], MAX(l.[派工加工状态]) AS [派工加工状态] FROM bd_dispatch h LEFT JOIN bl_dispatch l ON h.[单据编号]=l.[单据编号] GROUP BY h.[单据日期], h.asp_cancel, l.[生产车间], l.[工序名称], l.[计量单位]
GO
CREATE OR ALTER VIEW v_finish_in_detail AS SELECT h.*, l.[产品名称], l.[存货图片], l.[规格型号], l.[智能选单], l.[计量单位], l.[金额], l.[单价], l.[实收数量], l.[现存量], l.[现存量说明], l.[图号] FROM bd_finish_in h LEFT JOIN bl_finish_in l ON h.[单据编号]=l.[单据编号]
GO
CREATE OR ALTER VIEW v_finish_in_stats AS SELECT ROW_NUMBER() OVER(ORDER BY (SELECT NULL)) AS id, h.[单据日期], h.asp_cancel, l.[产品名称], l.[规格型号], l.[计量单位], COUNT(DISTINCT h.[单据编号]) AS [单据数], SUM(COALESCE(l.[实收数量],0)) AS [实收数量], SUM(COALESCE(l.[金额],0)) AS [金额] FROM bd_finish_in h LEFT JOIN bl_finish_in l ON h.[单据编号]=l.[单据编号] GROUP BY h.[单据日期], h.asp_cancel, l.[产品名称], l.[规格型号], l.[计量单位]
GO
CREATE OR ALTER VIEW v_manu_order_detail AS SELECT h.*, l.[生产类型], l.[产品编码], l.[存货图片], l.[产品名称], l.[规格型号], l.[型号], l.[适用BOM], l.[BOM展开方式], l.[生产单位], l.[数量], l.[齐套数量(主)], l.[累计汇报套数(工序单位)], l.[可用量], l.[可用量说明], l.[现存量], l.[现存量说明], l.[产品字符公用自定义项1], l.[图号], l.[单重], l.[总重], l.[需求令号] FROM bd_manu_order h LEFT JOIN bl_manu_order l ON h.[合同号]=l.[合同号]
GO
CREATE OR ALTER VIEW v_manu_order_stats AS SELECT ROW_NUMBER() OVER(ORDER BY (SELECT NULL)) AS id, h.asp_cancel, l.[产品名称], COUNT(DISTINCT h.[合同号]) AS [单据数], SUM(COALESCE(l.[数量],0)) AS [数量], SUM(COALESCE(l.[齐套数量(主)],0)) AS [齐套数量] FROM bd_manu_order h LEFT JOIN bl_manu_order l ON h.[合同号]=l.[合同号] GROUP BY h.asp_cancel, l.[产品名称]
GO
CREATE OR ALTER VIEW v_material_out_detail AS SELECT h.*, l.[材料名称], l.[计量单位], l.[数量], l.[单价], l.[金额], l.[规格型号], l.[手工确定成本], l.[明细备注], l.[现存量], l.[现存量说明] FROM bd_material_out h LEFT JOIN bl_material_out l ON h.[单据编号]=l.[单据编号]
